mapper.sql:
WHERE deleted = 0
AND status = #{status}
AND (LOWER(company_name) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(taxpayer_id) LIKE CONCAT('%', LOWER(#{keyword}), '%'))

mapper.select:
SELECT s.id AS subject_id, s.subject_name, t.id AS title_id, t.company_name FROM invoice_title_subject its INNER JOIN invoice_subject s ON s.id = its.subject_id AND s.deleted = 0 INNER JOIN invoice_title t ON t.id = its.title_id AND t.deleted = 0 AND t.status = 'PUBLISHED' WHERE its.subject_id IN #{subjectId}
AND t.id != #{excludeTitleId}
ORDER BY s.sort_no ASC, s.id ASC, t.id ASC FOR UPDATE
